def combination_sum(candidates, target):
    cands = sorted(candidates)
    out, path = [], []

    def walk(start, left):
        if left == 0:
            out.append(path[:])
            return
        for i in range(start, len(cands)):
            if cands[i] > left:
                break                    # sorted: the rest are bigger
            path.append(cands[i])
            walk(i, left - cands[i])     # i, not i + 1: reuse allowed
            path.pop()

    walk(0, target)
    return out

from functools import lru_cache


def word_break(s, words):
    words = set(words)

    @lru_cache(maxsize=None)
    def ok(i):                           # can s[i:] be split?
        if i == len(s):
            return True
        return any(s.startswith(w, i) and ok(i + len(w)) for w in words if w)

    return ok(0)

