def price_walk(n=300, seed=9, start=500):
    state = [seed]
    def rnd(k):
        state[0] = (state[0] * 6364136223846793005 + 1442695040888963407) % 18446744073709551616
        return (state[0] >> 33) % k
    prices, p = [], start
    for _ in range(n):
        p = max(1, p + rnd(41) - 20)
        prices.append(p)
    return prices
